document.addEventListener('DOMContentLoaded',()=>{
const PIN_URL=(()=>{const m=window.location.pathname.match(/^(\/arcanum\/?)/);return window.location.origin+(m?m[1]:'/')+'pin/verify';})();
function csrf(){return document.querySelector('meta[name="csrf-token"]')?.content||'';}
const mC=document.getElementById('modal-confirm'),mMsg=document.getElementById('modal-confirm-msg'),mOk=document.getElementById('modal-confirm-ok'),mCan=document.getElementById('modal-confirm-cancel');
function showConfirm(msg,cb){if(!mC){if(window.confirm(msg))cb();return;}if(mMsg)mMsg.textContent=msg;mC.style.display='flex';document.body.style.overflow='hidden';function close(){mC.style.display='none';document.body.style.overflow='';if(mOk)mOk.removeEventListener('click',ok);if(mCan)mCan.removeEventListener('click',close);mC.removeEventListener('click',bg);document.removeEventListener('keydown',esc);}function ok(){close();cb();}function bg(e){if(e.target===mC)close();}function esc(e){if(e.key==='Escape')close();}if(mOk)mOk.addEventListener('click',ok);if(mCan)mCan.addEventListener('click',close);mC.addEventListener('click',bg);document.addEventListener('keydown',esc);}
const mPin=document.getElementById('modal-pin'),pInp=document.getElementById('pin-input'),pBtn=document.getElementById('pin-submit'),pErr=document.getElementById('pin-error'),pCls=document.getElementById('pin-modal-close');
function showPin(cb){if(!mPin){cb();return;}if(pInp)pInp.value='';if(pErr){pErr.style.display='none';pErr.textContent='';}mPin.style.display='flex';document.body.style.overflow='hidden';setTimeout(()=>pInp?.focus(),80);
function close(){mPin.style.display='none';document.body.style.overflow='';if(pBtn)pBtn.removeEventListener('click',verify);if(pCls)pCls.removeEventListener('click',close);if(pInp)pInp.removeEventListener('keydown',key);document.removeEventListener('keydown',esc);}
async function verify(){const pin=(pInp?.value||'').trim();if(!pin){err('Ingresa tu PIN.');return;}pBtn.disabled=true;pBtn.textContent='...';try{const r=await fetch(PIN_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_token='+encodeURIComponent(csrf())+'&pin='+encodeURIComponent(pin),credentials:'same-origin'});const d=await r.json();if(d.ok){close();cb();}else if(d.locked){err(d.error||'Cuenta bloqueada. Sesión cerrada.');setTimeout(()=>{const m=window.location.pathname.match(/^(\/arcanum\/?)/);window.location.href=window.location.origin+(m?m[1]:'/')+'login';},2500);}else if(d.setup){close();const m=window.location.pathname.match(/^(\/arcanum\/?)/);window.location.href=window.location.origin+(m?m[1]:'/')+'profile';}else{err(d.error||'PIN incorrecto.');if(pInp){pInp.value='';pInp.focus();}}}catch{err('Error de red.');}finally{if(pBtn){pBtn.disabled=false;pBtn.textContent='Verificar';}}}
function err(m){if(pErr){pErr.textContent=m;pErr.style.display='block';}}
function key(e){if(e.key==='Enter')verify();}function esc(e){if(e.key==='Escape')close();}
if(pBtn)pBtn.addEventListener('click',verify);if(pCls)pCls.addEventListener('click',close);if(pInp)pInp.addEventListener('keydown',key);document.addEventListener('keydown',esc);}
document.querySelectorAll('form[data-confirm],form[data-pin-required]').forEach(form=>{
const nc=form.hasAttribute('data-confirm'),np=form.hasAttribute('data-pin-required');
form.addEventListener('submit',e=>{if(form.dataset.formReady==='1'){delete form.dataset.formReady;return;}e.preventDefault();const go=()=>{form.dataset.formReady='1';form.requestSubmit();};if(nc&&np){showConfirm(form.getAttribute('data-confirm')||'¿Confirmar?',()=>showPin(go));}else if(nc){showConfirm(form.getAttribute('data-confirm')||'¿Confirmar?',go);}else{showPin(go);}});});
document.querySelectorAll('input[type="file"][accept="application/pdf"]').forEach(inp=>{inp.addEventListener('change',()=>{const f=inp.files[0];if(!f)return;if(f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf')){window.alert('Seleccione un archivo PDF valido.');inp.value='';}});});
document.querySelectorAll('form[data-auto-filter]').forEach(f=>{const fs=f.querySelectorAll('input,select');let t=null;const s=()=>{clearTimeout(t);t=setTimeout(()=>f.requestSubmit(),450);};fs.forEach(fd=>{fd.addEventListener(fd.tagName==='SELECT'||fd.type==='date'?'change':'input',s);});});
document.querySelectorAll('[data-pdf-preview-form]').forEach(form=>{
const input=form.querySelector('[data-pdf-preview-input]'),preview=form.querySelector('[data-pdf-preview]'),emptyState=form.querySelector('[data-pdf-preview-empty]'),title=form.querySelector('[data-pdf-preview-title]'),trigger=form.querySelector('[data-pdf-pick]'),fileNameEl=form.querySelector('[data-file-name]');
let oUrl=null;if(!input||!preview)return;
if(trigger)trigger.addEventListener('click',()=>input.click());
if(fileNameEl)input.addEventListener('change',()=>{fileNameEl.textContent=input.files[0]?.name??'Sin archivo seleccionado';});
input.addEventListener('change',()=>{const f=input.files[0];if(oUrl){URL.revokeObjectURL(oUrl);oUrl=null;}if(!f||input.value==='')return;if(f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf'))return;oUrl=URL.createObjectURL(f);const fr=preview.parentElement;const pv=fr.querySelector('.pdf-dyn-obj');if(pv)pv.remove();const d=document.createElement('object');d.className='pdf-preview-object pdf-dyn-obj';d.type='application/pdf';d.setAttribute('data',oUrl+'#navpanes=0');fr.appendChild(d);preview.style.display='none';if(emptyState)emptyState.style.display='none';if(title)title.textContent=f.name;});
window.addEventListener('beforeunload',()=>{if(oUrl)URL.revokeObjectURL(oUrl);});});
document.querySelectorAll('[data-avatar-form]').forEach(form=>{
const input=form.querySelector('[data-avatar-input]'),img=form.querySelector('[data-avatar-preview]'),nameEl=form.querySelector('[data-avatar-name]'),trigger=form.querySelector('[data-avatar-pick]');
if(!input||!img)return;if(trigger)trigger.addEventListener('click',()=>input.click());
let aUrl=null;
input.addEventListener('change',()=>{const f=input.files[0];if(nameEl)nameEl.textContent=f?f.name:'Sin foto asignada';if(!f||!f.type.startsWith('image/'))return;if(aUrl)URL.revokeObjectURL(aUrl);aUrl=URL.createObjectURL(f);img.src=aUrl;});
window.addEventListener('beforeunload',()=>{if(aUrl)URL.revokeObjectURL(aUrl);});});
});

/* 6. Campos de fecha: abrir el calendario nativo al hacer clic en el campo */
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('input[type="date"]').forEach((f)=>{f.addEventListener('click',()=>{if(typeof f.showPicker==='function'){try{f.showPicker()}catch(e){}}});});});
